import type { PoolClient } from "pg";
import { query, queryOne, type DbExecutor } from "./db";

export interface Migration {
  version: number;
  name: string;
  sql: string;
}

/**
 * Postgres dialect baseline. Port notes from the SQLite schema:
 * - INTEGER PRIMARY KEY AUTOINCREMENT -> BIGINT GENERATED BY DEFAULT AS IDENTITY
 * - email/code COLLATE NOCASE -> CITEXT (case-insensitive equality + uniqueness;
 *   load-bearing for login and promo-code matching)
 * - TEXT timestamps with datetime('now') defaults -> TIMESTAMPTZ DEFAULT now()
 *   (db.ts registers a type parser so they still reach the app as strings)
 * - sessions.expires_at stays BIGINT epoch-ms, exactly as the SQLite schema had it
 * - banned/active stay INTEGER 0/1 so types.ts is unchanged
 * - promotions.expires_at stays TEXT: it holds a date-only string (YYYY-MM-DD)
 *   that app code compares lexicographically
 */
const BASELINE = `
CREATE EXTENSION IF NOT EXISTS citext;
CREATE TABLE IF NOT EXISTS users (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email CITEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  name TEXT NOT NULL,
  city TEXT NOT NULL DEFAULT '',
  zip TEXT NOT NULL DEFAULT '',
  bio TEXT NOT NULL DEFAULT '',
  role TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('user','admin')),
  banned INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS sessions (
  token_hash TEXT PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at BIGINT NOT NULL
);
CREATE TABLE IF NOT EXISTS listings (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  seller_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  description TEXT NOT NULL,
  price_cents INTEGER NOT NULL CHECK (price_cents > 0),
  category TEXT NOT NULL,
  condition TEXT NOT NULL,
  quantity INTEGER NOT NULL CHECK (quantity >= 0),
  city TEXT NOT NULL DEFAULT '',
  zip TEXT NOT NULL DEFAULT '',
  image TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','removed')),
  flag_count INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_listings_seller ON listings(seller_id);
CREATE INDEX IF NOT EXISTS idx_listings_cat ON listings(category);
CREATE TABLE IF NOT EXISTS flags (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  listing_id BIGINT NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
  reporter_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  reason TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (listing_id, reporter_id)
);
CREATE TABLE IF NOT EXISTS messages (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sender_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  recipient_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  listing_id BIGINT REFERENCES listings(id) ON DELETE SET NULL,
  body TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS offers (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  listing_id BIGINT NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
  buyer_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  amount_cents INTEGER NOT NULL CHECK (amount_cents > 0),
  quantity INTEGER NOT NULL DEFAULT 1 CHECK (quantity > 0),
  status TEXT NOT NULL DEFAULT 'pending',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS orders (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  listing_id BIGINT NOT NULL REFERENCES listings(id),
  buyer_id BIGINT NOT NULL REFERENCES users(id),
  seller_id BIGINT NOT NULL REFERENCES users(id),
  offer_id BIGINT REFERENCES offers(id),
  quantity INTEGER NOT NULL,
  unit_price_cents INTEGER NOT NULL,
  discount_cents INTEGER NOT NULL DEFAULT 0,
  total_cents INTEGER NOT NULL,
  promo_code TEXT,
  status TEXT NOT NULL DEFAULT 'pending_payment',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS buyback_requests (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  description TEXT NOT NULL,
  condition TEXT NOT NULL,
  asking_cents INTEGER,
  quote_cents INTEGER,
  admin_note TEXT,
  status TEXT NOT NULL DEFAULT 'submitted',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS promotions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code CITEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  percent_off INTEGER NOT NULL CHECK (percent_off BETWEEN 1 AND 90),
  seller_id BIGINT REFERENCES users(id) ON DELETE CASCADE,
  listing_id BIGINT REFERENCES listings(id) ON DELETE CASCADE,
  category TEXT,
  max_uses INTEGER,
  uses INTEGER NOT NULL DEFAULT 0,
  expires_at TEXT,
  active INTEGER NOT NULL DEFAULT 1,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
`;

/**
 * Migrations run in version order, each inside its own transaction on the
 * client handed in; the applied version is recorded in schema_migrations.
 * They run as an explicit deploy step (scripts/migrate.ts) or from the seed
 * script — never lazily from request code (serverless cold starts would race).
 * The baseline (v1) is idempotent (CREATE TABLE IF NOT EXISTS), so
 * pre-existing databases adopt it cleanly.
 */
export const MIGRATIONS: Migration[] = [
  { version: 1, name: "baseline", sql: BASELINE },
  {
    version: 2,
    name: "offer_inventory_reservation",
    sql: `
ALTER TABLE listings ADD COLUMN reserved_quantity INTEGER NOT NULL DEFAULT 0;
ALTER TABLE offers ADD COLUMN expires_at TIMESTAMPTZ;
`,
  },
  {
    version: 3,
    name: "order_fees_and_seller_tier",
    sql: `
-- Seller tier (decided 2026-11-21): FREE $0 forever, PREMIUM $14.99/mo drops
-- the shipped platform fee from 9.9% to 6.9%. The Stripe step selects the
-- fee bps by the seller's tier in createOrder().
ALTER TABLE users ADD COLUMN tier TEXT NOT NULL DEFAULT 'free' CHECK (tier IN ('free', 'premium'));
-- Order money fields for the Stripe step (decided 2026-11-21): fee base is
-- item price + shipping charged, never sales tax; 9.9% shipped / 6.9% premium
-- shipped / 0% local pickup. stripe_payment_intent_id holds the Stripe
-- PaymentIntent created for the order's pay step (test mode on staging).
ALTER TABLE orders ADD COLUMN delivery_method TEXT NOT NULL DEFAULT 'shipped' CHECK (delivery_method IN ('shipped', 'local'));
ALTER TABLE orders ADD COLUMN shipping_cents INTEGER NOT NULL DEFAULT 0 CHECK (shipping_cents >= 0);
ALTER TABLE orders ADD COLUMN tax_cents INTEGER NOT NULL DEFAULT 0 CHECK (tax_cents >= 0);
ALTER TABLE orders ADD COLUMN platform_fee_cents INTEGER NOT NULL DEFAULT 0 CHECK (platform_fee_cents >= 0);
ALTER TABLE orders ADD COLUMN stripe_payment_intent_id TEXT;
`,
  },
];

export async function migrate(client: PoolClient): Promise<void> {
  await client.query(
    `CREATE TABLE IF NOT EXISTS schema_migrations (
      version INTEGER PRIMARY KEY,
      applied_at TIMESTAMPTZ NOT NULL DEFAULT now()
    )`
  );
  const applied = new Set((await query<{ version: number }>("SELECT version FROM schema_migrations", [], client)).map((r) => r.version));
  const known = new Set(MIGRATIONS.map((m) => m.version));
  for (const v of applied) {
    if (!known.has(v)) throw new Error(`Database is at migration ${v}, newer than this code knows — update the app first`);
  }
  for (const m of [...MIGRATIONS].sort((a, b) => a.version - b.version)) {
    if (applied.has(m.version)) continue;
    await client.query("BEGIN");
    try {
      await client.query(m.sql);
      await client.query("INSERT INTO schema_migrations (version) VALUES ($1)", [m.version]);
      await client.query("COMMIT");
    } catch (e) {
      await client.query("ROLLBACK").catch(() => {});
      throw e;
    }
  }
}

export async function currentSchemaVersion(exec: DbExecutor): Promise<number> {
  const row = await queryOne<{ v: number | null }>("SELECT MAX(version) AS v FROM schema_migrations", [], exec);
  return row?.v ?? 0;
}
